import openpyxl, re
files = ["CUSTO PRODUTOS CONFEITARIA atual.xlsx","PREÇO DE CUSTO MOMMA 02.xlsx","lista produtos momma.xlsx"]
kw = re.compile(r"bobina|adesiv|papel acopl|\bpote\b|lacre|vidro|r[oó]tulo|laminad|celofane|forminha|p[eé]tala|tapetinho|saquinho|arame|caixa|cakeboard|cake board|embalag|base de papel|base laminad", re.I)
for f in files:
    print("\n==================== ",f," ====================")
    try:
        wb = openpyxl.load_workbook(f, data_only=True, read_only=True)
    except Exception as e:
        print("ERRO:",e); continue
    print("ABAS:", wb.sheetnames)
    for ws in wb.worksheets:
        hits=[]
        for row in ws.iter_rows(values_only=True):
            cells=[str(c) for c in row if c is not None]
            line=" | ".join(cells)
            if line.strip() and kw.search(line):
                hits.append(line)
        if hits:
            print(f"  --- aba '{ws.title}': {len(hits)} linhas com embalagem ---")
            for h in hits[:40]:
                print("    ", h[:160])
